TriggerOraclev10g.body:
DECLARE
    v_data_plasare detalii_comanda.data_plasare%TYPE;
BEGIN
    SELECT data_plasare INTO v_data_plasare
    FROM detalii_comanda
    WHERE cod_comanda = :new.cod_comanda;

    IF :new.data_ridicare < v_data_plasare THEN
        RAISE_APPLICATION_ERROR(-20002, 
            'Eroare: Data ridicare (' || TO_CHAR(:new.data_ridicare, 'DD.MM.YYYY') || 
            ') nu poate fi inainte de data plasarii (' || TO_CHAR(v_data_plasare, 'DD.MM.YYYY') || ').');
    END IF;
EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RAISE_APPLICATION_ERROR(-20004, 'Comanda inexistenta.');
END;
